-- seed.sql — paste into the Supabase SQL editor to load/refresh the events.
-- Safe to run repeatedly: it upserts on id.

on conflict (id) do update set
  layer = excluded.layer,
  track = excluded.track,
  title = excluded.title,
  date = excluded.date,
  "endDate" = excluded."endDate",
  "start" = excluded."start",
  "end" = excluded."end",
  repeat = excluded.repeat,
  until = excluded.until,
  "skipBreaks" = excluded."skipBreaks",
  "where" = excluded."where",
  host = excluded.host,
  link = excluded.link,
  notes = excluded.notes,
  committee = excluded.committee,
  unconfirmed = excluded.unconfirmed,
  "isBreak" = excluded."isBreak",
  updated_at = now();
